@msig trait EnergySafePlanComposer_supervision_energySafePlanComposer_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.HVACSupervisor_Instance_supervision_energySafePlanComposer)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.HVACSupervisor_Instance_supervision_energySafePlanComposer)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.HVACSupervisor_Instance_supervision_energySafePlanComposer)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.HVACSupervisor_Instance_supervision_energySafePlanComposer)
  }

  /** helper function to set the values of all input ports.
   * @param electricalEligibility payload for data port electricalEligibility
   * @param selectedIntent payload for data port selectedIntent
   */
  def put_concrete_inputs(electricalEligibility : HVAC_Visibility_Priority_Supervisor.ElectricalEligibility,
                          selectedIntent : HVAC_Visibility_Priority_Supervisor.SelectedIntent): Unit = {
    put_electricalEligibility(electricalEligibility)
    put_selectedIntent(selectedIntent)
  }


  /** helper function to check EnergySafePlanComposer_supervision_energySafePlanComposer's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param candidatePlan method that will be called with the value of the outgoing data
   *        port 'candidatePlan'.
   */
  def check_concrete_output(candidatePlan: HVAC_Visibility_Priority_Supervisor.CandidatePlan => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val candidatePlanValue: HVAC_Visibility_Priority_Supervisor.CandidatePlan = get_candidatePlan().get
    if(!candidatePlan(candidatePlanValue)) {
      testFailures = testFailures :+ st"'candidatePlan' did not match expected: value of the outgoing data port is ${candidatePlanValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_electricalEligibility(value : HVAC_Visibility_Priority_Supervisor.ElectricalEligibility): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_energySafePlanComposer.operational_api.electricalEligibility_Id, HVAC_Visibility_Priority_Supervisor.ElectricalEligibility_Payload(value))
  }

  // setter for in DataPort
  def put_selectedIntent(value : HVAC_Visibility_Priority_Supervisor.SelectedIntent): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_energySafePlanComposer.operational_api.selectedIntent_Id, HVAC_Visibility_Priority_Supervisor.SelectedIntent_Payload(value))
  }

  // getter for out DataPort
  def get_candidatePlan(): Option[HVAC_Visibility_Priority_Supervisor.CandidatePlan] = {
    val value: Option[HVAC_Visibility_Priority_Supervisor.CandidatePlan] = get_candidatePlan_payload() match {
      case Some(HVAC_Visibility_Priority_Supervisor.CandidatePlan_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port candidatePlan.  Expecting 'HVAC_Visibility_Priority_Supervisor.CandidatePlan_Payload' but received ${v}")
      case _ => None[HVAC_Visibility_Priority_Supervisor.CandidatePlan]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_candidatePlan_payload(): Option[HVAC_Visibility_Priority_Supervisor.CandidatePlan_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_energySafePlanComposer.initialization_api.candidatePlan_Id).asInstanceOf[Option[HVAC_Visibility_Priority_Supervisor.CandidatePlan_Payload]]
  }

}
